def load_table(name):
    try:
        return pd.read_csv(FILES[name]).fillna("")
    except Exception:
        return pd.DataFrame()

def save_table(name, df):
    df.to_csv(FILES[name], index=False)

def add_row(name, row):
    df = load_table(name)
    df = pd.concat([df, pd.DataFrame([row])], ignore_index=True)
    save_table(name, df)

def availability(df):
    op = pd.to_numeric(df.get("Operating time (h)", 0), errors="coerce").fillna(0)
    down = pd.to_numeric(df.get("Downtime (h)", 0), errors="coerce").fillna(0)
    total = op + down
    return np.where(total > 0, op / total * 100, 0)

def condition_label(temp, vib):
    if temp > 100 or vib > 8:
        return "CRITICAL"
    if temp >= 80 or vib >= 5:
        return "WARNING"
    return "NORMAL"

def risk_label(score):
    if score >= 17: return "Critical"
    if score >= 10: return "High"
    if score >= 5: return "Medium"
    return "Low"

def prepare_equipment(df):
    if df.empty: return df
    df = df.copy()
    df["Temperature (°C)"] = pd.to_numeric(df["Temperature (°C)"], errors="coerce").fillna(0)
    df["Vibration (mm/s)"] = pd.to_numeric(df["Vibration (mm/s)"], errors="coerce").fillna(0)
    df["Operating time (h)"] = pd.to_numeric(df["Operating time (h)"], errors="coerce").fillna(0)
    df["Downtime (h)"] = pd.to_numeric(df["Downtime (h)"], errors="coerce").fillna(0)
    df["Availability (%)"] = np.round(availability(df), 2)
    df["Condition alert"] = [condition_label(t, v) for t, v in zip(df["Temperature (°C)"], df["Vibration (mm/s)"])]
    return df

