alerts = []
for _, r in workers.iterrows():
    if str(r.get("PPE compliance","")) == "No":
        alerts.append({"Priority":"High","Area":"Worker safety","Record":r.get("Worker ID",""),"Alert":"PPE non-compliance"})
    if str(r.get("Fatigue level","")) == "High":
        alerts.append({"Priority":"High","Area":"Worker safety","Record":r.get("Worker ID",""),"Alert":"High fatigue level"})
    if str(r.get("Safety training","")) == "Expired":
        alerts.append({"Priority":"Medium","Area":"Worker safety","Record":r.get("Worker ID",""),"Alert":"Safety training expired"})
for _, r in equipment.iterrows():
    if r.get("Condition alert") in ["WARNING","CRITICAL"]:
        alerts.append({"Priority":"Critical" if r.get("Condition alert")=="CRITICAL" else "Medium","Area":"Equipment","Record":r.get("Equipment ID",""),"Alert":f'{r.get("Condition alert")} condition: temperature {r.get("Temperature (°C)")} °C; vibration {r.get("Vibration (mm/s)")} mm/s'})
    if str(r.get("Maintenance due","")) == "Yes":
        alerts.append({"Priority":"High","Area":"Maintenance","Record":r.get("Equipment ID",""),"Alert":"Maintenance due/overdue"})
    if float(r.get("Availability (%)",0) or 0) < 85:
        alerts.append({"Priority":"High","Area":"Maintenance","Record":r.get("Equipment ID",""),"Alert":"Low equipment availability"})
for _, r in incidents.iterrows():
    if str(r.get("Severity","")) in ["Critical","High"] and str(r.get("Incident status","")) != "Closed":
        alerts.append({"Priority":"Critical","Area":"Incident","Record":r.get("Incident ID",""),"Alert":"High-severity incident not closed"})
for _, r in observations.iterrows():
    try: score = int(r.get("Likelihood",1))*int(r.get("Consequence",1))
    except Exception: score = 0
    if score >= 10 and str(r.get("Status","")) != "Closed":
        alerts.append({"Priority":"High" if score < 17 else "Critical","Area":"Risk observation","Record":r.get("Observation ID",""),"Alert":f"High-risk observation (score {score})"})

